-- 조회 1: 회원 ID 로 프로필 한 번에
CREATE TABLE member_profile_by_id (
  member_id bigint PRIMARY KEY,
  grade text, nickname text, updated_at timestamp, version bigint
);

-- 조회 2: 상품 ID 묶음으로 지면용 요약
CREATE TABLE product_summary_by_id (
  product_id bigint PRIMARY KEY,
  name text, price bigint, sale_price bigint, version bigint
);
-- 지면은 SELECT ... WHERE product_id IN (...) 대신
-- 여러 건을 병렬로 단건 조회하는 쪽이 보통 권장된다

WEIGHTS = {"new_device": 40, "new_country": 30, "impossible_travel": 50, "many_failures": 25}

def decide(signals):
    score = sum(WEIGHTS[s] for s in signals)
    if score >= 80:
        return score, "막고 본인에게 알림"
    if score >= 40:
        return score, "추가 인증(2FA) 요구"
    return score, "통과"

for case in [[], ["new_device"], ["new_device", "new_country"], ["impossible_travel", "many_failures", "new_device"]]:
    print(case, decide(case))

# 출력
# [] (0, '통과')
# ['new_device'] (40, '추가 인증(2FA) 요구')
# ['new_device', 'new_country'] (70, '추가 인증(2FA) 요구')
# ['impossible_travel', 'many_failures', 'new_device'] (115, '막고 본인에게 알림')
